{
  "os": {
    "system": "Windows",
    "release": "10",
    "architecture": "AMD64"
  },
  "shell": "C:\\WINDOWS\\system32\\cmd.exe",
  "python": {
    "version": "3.12.13",
    "executable": "E:\\codex\\yl-code-agent\\.venv\\Scripts\\python.exe"
  },
  "cwd": "E:\\codex\\yl-code-agent",
  "available_commands": {
    "python": true,
    "uv": true,
    "git": true,
    "ruff": true,
    "mypy": true,
    "pytest": true
  },
  "project": {
    "name": "codeAgent",
    "requires_python": ">=3.12,<3.13",
    "configured_tools": [
      "hatch",
      "ruff",
      "mypy",
      "pytest"
    ],
    "ruff": {
      "src": [
        "src"
      ],
      "line-length": 100,
      "target-version": "py312",
      "lint": {
        "select": [
          "E",
          "F",
          "I",
          "UP"
        ],
        "ignore": []
      }
    },
    "mypy": {
      "python_version": "3.12",
      "strict": true,
      "mypy_path": "src",
      "explicit_package_bases": true
    }
  }
}

